<?php
declare(strict_types=1);
session_start();
$root=dirname(__DIR__,3);
$cfg=require $root.'/config.php';
date_default_timezone_set($cfg['timezone']??'America/Argentina/Buenos_Aires');
$db=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function go(string $u):never{header('Location: '.$u);exit;}
function csrf():void{if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(419);exit('Solicitud vencida.');}}
function admin():bool{return ($_SESSION['user']['role']??'')==='admin';}
function mon(float $n,string $c):string{return ($c==='USD'?'US$ ':'$ ').number_format($n,2,',','.');}
function brandFromCategory(string $cat):string{$x=mb_strtolower($cat);if(str_contains($x,'c4'))return 'Control4';if(str_contains($x,'shelly'))return 'Shelly';if(str_contains($x,'domot'))return 'LifeSmart';return 'Otro';}
function replaceCharge(PDO $db,int $projectId,int $newChargeId,array $types):void{$m=implode(',',array_fill(0,count($types),'?'));$s=$db->prepare("SELECT id FROM charges WHERE project_id=? AND active=1 AND id<>? AND type IN ($m)");$s->execute(array_merge([$projectId,$newChargeId],$types));foreach($s as $old){$als=$db->prepare('SELECT payment_id,amount FROM allocations WHERE charge_id=?');$als->execute([$old['id']]);foreach($als as $al)$db->prepare('INSERT INTO allocations(payment_id,charge_id,amount) VALUES(?,?,?) ON DUPLICATE KEY UPDATE amount=amount+VALUES(amount)')->execute([$al['payment_id'],$newChargeId,$al['amount']]);$db->prepare('DELETE FROM allocations WHERE charge_id=?')->execute([$old['id']]);$db->prepare('UPDATE charges SET active=0 WHERE id=?')->execute([$old['id']]);}}
if(empty($_SESSION['user']))go('index.php');
$_SESSION['csrf']??=bin2hex(random_bytes(24));
$a=$_GET['a']??'new_quote';

if($a==='save_quote'){
 if(!admin()){http_response_code(403);exit('No autorizado.');}
 csrf();
 try{
  $pid=(int)($_POST['project_id']??0);$clientId=(int)($_POST['client_id']??0);$priceListId=(int)($_POST['price_list_id']??0);
  $ps=$db->prepare('SELECT p.*,c.id client_id FROM projects p JOIN clients c ON c.id=p.client_id WHERE p.id=? AND c.id=?');$ps->execute([$pid,$clientId]);$project=$ps->fetch();if(!$project)throw new Exception('Seleccioná un proyecto válido del cliente.');
  $families=array_values(array_intersect(['lifesmart','control4','shelly'],$_POST['quote_families']??[]));if(!$families)throw new Exception('Seleccioná al menos una familia comercial.');
  $template=$_POST['quote_template_family']??'';if(!in_array($template,$families,true))$template=$families[0];
  $pls=$db->prepare('SELECT id,name,currency FROM price_lists WHERE id=? AND active=1');$pls->execute([$priceListId]);$pl=$pls->fetch();if(!$pl)throw new Exception('Seleccioná una lista de precios válida.');$currency=$pl['currency'];
  $items=[];$materials=0.0;$sort=0;$prodQ=$db->prepare("SELECT p.id,p.sku,p.name,p.unit,COALESCE(pc.name,'Otros') category FROM products p LEFT JOIN product_categories pc ON pc.id=p.category_id WHERE p.id=? AND p.active=1");
  foreach($_POST['items']??[] as $r){$productId=(int)($r['product_id']??0);$qty=max(0,(float)($r['quantity']??0));if(!$productId||$qty<=0)continue;$prodQ->execute([$productId]);$prod=$prodQ->fetch();if(!$prod)continue;$unit=max(0,(float)($r['unit_price']??0));$sub=round($qty*$unit,2);$materials+=$sub;$brand=trim((string)($r['brand']??''))?:brandFromCategory($prod['category']);$items[]=[$productId,$prod['category'],$brand,$prod['sku'],$prod['name'],$prod['unit'],$qty,$unit,$priceListId,$sub,$sort++];}
  if(!$items)throw new Exception('Agregá al menos un producto al presupuesto.');
  $labor=max(0,(float)($_POST['labor_amount']??0));$matMode=$_POST['materials_tax_mode']??'sin_iva';$matVat=(float)($_POST['materials_vat_rate']??21);$labMode=$_POST['labor_tax_mode']??'sin_iva';$labVat=(float)($_POST['labor_vat_rate']??21);$factor=static fn(string $m,float $v):float=>$m==='mas_iva'?1+$v/100:1;$matTotal=round($materials*$factor($matMode,$matVat),2);$labTotal=round($labor*$factor($labMode,$labVat),2);$total=$matTotal+$labTotal;$version=max(1,(int)($_POST['version_no']??1));$date=$_POST['quote_date']??date('Y-m-d');$status=$_POST['status']??'borrador';$category=$_POST['quote_category']??'general';$notes=trim((string)($_POST['notes']??''));
  $db->beginTransaction();$db->prepare('INSERT INTO quotes(project_id,version_no,quote_category,currency,quote_date,quote_families,quote_template_family,price_list_id,materials_amount,labor_amount,subtotal,tax_mode,vat_rate,materials_tax_mode,materials_vat_rate,labor_tax_mode,labor_vat_rate,total,status,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$pid,$version,$category,$currency,$date,implode(',',$families),$template,$priceListId,$materials,$labor,$materials+$labor,'sin_iva',21,$matMode,$matVat,$labMode,$labVat,$total,$status,$notes]);$qid=(int)$db->lastInsertId();
  $ins=$db->prepare('INSERT INTO quote_items(quote_id,product_id,category,brand,sku,description,unit,quantity,unit_price,price_list_id,subtotal,sort_order) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');foreach($items as $r)$ins->execute(array_merge([$qid],$r));
  if($status==='aprobado_inicial'){$pct=(float)$project['engineering_pct'];$amt=round($total*$pct/100,2);$db->prepare("INSERT INTO charges(project_id,quote_id,charge_date,type,currency,description,amount) VALUES(?,?,?,'ingenieria',?,?,?)")->execute([$pid,$qid,$date,$currency,'Adelanto de ingeniería '.$pct.'% · v'.$version,$amt]);$eng=(int)$db->lastInsertId();replaceCharge($db,$pid,$eng,['ingenieria']);$db->prepare("UPDATE projects SET status='aprobado' WHERE id=?")->execute([$pid]);}
  if($status==='final'){$db->prepare("INSERT INTO charges(project_id,quote_id,charge_date,type,currency,description,amount) VALUES(?,?,?,'materiales',?,?,?)")->execute([$pid,$qid,$date,$currency,'Materiales · presupuesto final v'.$version,$matTotal]);$mat=(int)$db->lastInsertId();replaceCharge($db,$pid,$mat,['materiales']);if($labTotal>0){$db->prepare("INSERT INTO charges(project_id,quote_id,charge_date,type,currency,description,amount) VALUES(?,?,?,'mano_obra',?,?,?)")->execute([$pid,$qid,$date,$currency,'Mano de obra · presupuesto final v'.$version,$labTotal]);$lab=(int)$db->lastInsertId();replaceCharge($db,$pid,$lab,['ingenieria','mano_obra']);}$db->prepare("UPDATE projects SET status='en_obra' WHERE id=?")->execute([$pid]);}
  $db->commit();$_SESSION['msg']='Presupuesto creado desde el catálogo.';go('index.php?a=quote_view&id='.$qid);
 }catch(Throwable $ex){if($db->inTransaction())$db->rollBack();$_SESSION['msg']='No se pudo guardar: '.$ex->getMessage();go('index.php?a=new_quote');}
}

if(in_array($a,['quote_view','quote_print'],true)){
 $id=(int)($_GET['id']??0);$s=$db->prepare("SELECT q.*,p.project_number,p.name project_name,c.business_name,c.contact_name FROM quotes q JOIN projects p ON p.id=q.project_id JOIN clients c ON c.id=p.client_id WHERE q.id=?");$s->execute([$id]);$q=$s->fetch();if(!$q){http_response_code(404);exit('Presupuesto inexistente.');}$is=$db->prepare('SELECT * FROM quote_items WHERE quote_id=? ORDER BY sort_order,id');$is->execute([$id]);$items=$is->fetchAll();$print=$a==='quote_print';?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Presupuesto <?=e($q['project_number'])?> v<?=e($q['version_no'])?></title><style>*{box-sizing:border-box}body{margin:0;background:#eef1f4;color:#252b32;font:14px/1.45 Arial,sans-serif}.sheet{width:210mm;min-height:297mm;margin:18px auto;background:#fff;padding:18mm}.top{display:flex;justify-content:space-between;border-bottom:4px solid #ff6702;padding-bottom:14px}.brand{font-size:28px;font-weight:800}.meta{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:24px 0}.box{border:1px solid #ddd;border-radius:8px;padding:12px}table{width:100%;border-collapse:collapse}th,td{padding:9px 7px;border-bottom:1px solid #ddd}th{text-align:left;background:#f5f6f7;font-size:11px;text-transform:uppercase}.right{text-align:right}.actions{width:210mm;margin:0 auto 18px;display:flex;gap:10px}.btn{padding:10px 14px;background:#ff6702;color:#fff;text-decoration:none;border-radius:7px;font-weight:700}.total{margin:22px 0 0 auto;width:330px}.total div{display:flex;justify-content:space-between;padding:6px 0}.grand{border-top:2px solid #252b32;font-size:20px;font-weight:800}@media print{body{background:#fff}.actions{display:none}.sheet{margin:0}}@media(max-width:900px){.sheet,.actions{width:auto;margin:0}.sheet{padding:22px}}</style></head><body><?php if(!$print):?><div class="actions"><a class="btn" href="?a=quotes">← Presupuestos</a><a class="btn" href="?a=quote_print&id=<?=$id?>" target="_blank">Vista para PDF</a></div><?php endif;?><section class="sheet"><div class="top"><div><div class="brand">● Punto Domótica</div><div>Casas inteligentes</div></div><div class="right"><b>PRESUPUESTO</b><br><?=e(date('d/m/Y',strtotime($q['quote_date'])))?></div></div><div class="meta"><div class="box"><b>Cliente</b><br><?=e($q['business_name'])?></div><div class="box"><b>Proyecto</b><br><?=e($q['project_number'].' · '.$q['project_name'])?><br>Versión <?=e($q['version_no'])?> · <?=e($q['currency'])?></div></div><h2>Equipamiento</h2><table><thead><tr><th>Referencia interna</th><th>Producto</th><th>Marca</th><th>Cant.</th><th class="right">Unitario</th><th class="right">Subtotal</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><b><?=e($it['sku']?:'—')?></b></td><td><?=e($it['description'])?><br><small><?=e($it['category'])?></small></td><td><?=e($it['brand'])?></td><td><?=e(number_format((float)$it['quantity'],2,',','.'))?></td><td class="right"><?=e(mon((float)$it['unit_price'],$q['currency']))?></td><td class="right"><?=e(mon((float)$it['subtotal'],$q['currency']))?></td></tr><?php endforeach;?></tbody></table><div class="total"><div><span>Materiales</span><b><?=e(mon((float)$q['materials_amount'],$q['currency']))?></b></div><?php if((float)$q['labor_amount']>0):?><div><span>Mano de obra</span><b><?=e(mon((float)$q['labor_amount'],$q['currency']))?></b></div><?php endif;?><div class="grand"><span>Total</span><span><?=e(mon((float)$q['total'],$q['currency']))?></span></div></div></section><?php if($print):?><script>window.addEventListener('load',()=>setTimeout(()=>window.print(),250));</script><?php endif;?></body></html><?php exit;
}

$clients=$db->query("SELECT id,business_name,contact_name FROM clients WHERE active=1 ORDER BY business_name")->fetchAll();$projects=$db->query("SELECT id,client_id,project_number,name FROM projects ORDER BY id DESC")->fetchAll();$lists=$db->query("SELECT id,name,currency,base_price_list_id,discount_percentage FROM price_lists WHERE active=1 ORDER BY currency,name")->fetchAll();$products=$db->query("SELECT p.id,p.sku,p.name,p.unit,COALESCE(pc.name,'Otros') category FROM products p LEFT JOIN product_categories pc ON pc.id=p.category_id WHERE p.active=1 ORDER BY pc.name,p.name")->fetchAll();$prices=$db->query("SELECT product_id,price_list_id,price,currency FROM product_prices")->fetchAll();$maxv=$db->query('SELECT project_id,MAX(version_no) maxv FROM quotes GROUP BY project_id')->fetchAll();$versions=[];foreach($maxv as $v)$versions[(int)$v['project_id']]=(int)$v['maxv']+1;$preProject=(int)($_GET['project_id']??0);$preClient=0;foreach($projects as $p)if((int)$p['id']===$preProject)$preClient=(int)$p['client_id'];$msg=$_SESSION['msg']??null;unset($_SESSION['msg']);
$productJson=[];foreach($products as $p)$productJson[(int)$p['id']]=['id'=>(int)$p['id'],'sku'=>$p['sku'],'name'=>$p['name'],'unit'=>$p['unit'],'category'=>$p['category'],'brand'=>brandFromCategory($p['category'])];$priceJson=[];foreach($prices as $p)$priceJson[(int)$p['price_list_id']][(int)$p['product_id']]=(float)$p['price'];$listJson=[];foreach($lists as $l)$listJson[(int)$l['id']]=['id'=>(int)$l['id'],'currency'=>$l['currency'],'base'=>(int)($l['base_price_list_id']??0),'discount'=>$l['discount_percentage']===null?null:(float)$l['discount_percentage']];
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nuevo presupuesto · Punto ERP</title><style>:root{--o:#ff6702;--dark:#171b20;--ink:#27303b;--muted:#6e7781;--line:#e1e5e9;--bg:#f4f6f8;--sidebar:270px}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 system-ui}.sidebar{position:fixed;inset:0 auto 0 0;width:var(--sidebar);padding:28px 18px;background:var(--dark);color:#fff}.nav{display:flex;flex-direction:column;gap:5px;padding:24px 0}.nav a{padding:11px 13px;border-radius:9px;color:#d8dde3;text-decoration:none;font-weight:600}.nav a.active{background:var(--o);color:#fff}.main{margin-left:var(--sidebar);padding:32px 4%}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:15px}.c3{grid-column:span 3}.c4{grid-column:span 4}.c6{grid-column:span 6}.c12{grid-column:span 12}label{display:block;font-weight:700;margin-bottom:6px}input,select,textarea{width:100%;padding:10px;border:1px solid #cbd1d7;border-radius:8px;background:#fff;font:inherit}input[type=checkbox]{width:auto}.families{display:flex;gap:10px;flex-wrap:wrap}.families label{padding:10px 13px;border:1px solid var(--line);border-radius:9px}.btn{border:0;border-radius:8px;padding:10px 14px;background:var(--o);color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.btn.gray{background:#e9edf0;color:#28313a}.muted{color:var(--muted)}.flash{padding:12px 15px;background:#fff0e5;border:1px solid #ffd2b1;border-radius:9px;margin-bottom:18px}.items{overflow:auto}.items table{width:100%;border-collapse:collapse;min-width:1120px}.items th,.items td{padding:8px;border-bottom:1px solid var(--line);vertical-align:top}.items th{text-align:left;font-size:11px;text-transform:uppercase;color:var(--muted)}.ref{font-weight:700;white-space:nowrap}@media(max-width:900px){.sidebar{position:static;width:auto}.main{margin-left:0;padding:22px 18px}.c3,.c4,.c6{grid-column:span 12}}</style></head><body><aside class="sidebar"><nav class="nav"><a href="index.php">Panel general</a><a href="?a=clients">Clientes</a><a href="?a=products">Productos</a><a href="?a=projects">Proyectos</a><a class="active" href="?a=quotes">Presupuestos</a><a href="?a=receipts">Recibos y pagos</a></nav></aside><main class="main"><?php if($msg):?><div class="flash"><?=e($msg)?></div><?php endif;?><h1>Nuevo presupuesto</h1><form method="post" action="?a=save_quote"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><div class="card"><h2>1. Cliente y proyecto</h2><div class="grid"><p class="c6"><label>Cliente</label><select id="client" name="client_id" required><option value="">Seleccionar cliente…</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>" <?=$preClient===(int)$c['id']?'selected':''?>><?=e($c['business_name'])?></option><?php endforeach;?></select></p><p class="c6"><label>Proyecto</label><select id="project" name="project_id" required><option value="">Seleccionar proyecto…</option></select></p><p class="c3"><label>Versión</label><input id="version" type="number" min="1" name="version_no" value="1" required></p><p class="c3"><label>Fecha</label><input type="date" name="quote_date" value="<?=date('Y-m-d')?>" required></p><p class="c3"><label>Estado</label><select name="status"><option value="borrador">Borrador</option><option value="enviado">Enviado</option><option value="aprobado_inicial">Aprobado inicial</option><option value="final">Final</option></select></p><p class="c3"><label>Rubro</label><select name="quote_category"><option value="general">General</option><option value="domotica">Domótica</option><option value="redes">Redes</option><option value="camaras">Cámaras</option><option value="alarma">Alarma</option><option value="audio">Audio</option></select></p></div></div><div class="card"><h2>2. Tipo</h2><div class="families"><label><input class="fam" type="checkbox" name="quote_families[]" value="lifesmart" checked> LifeSmart</label><label><input class="fam" type="checkbox" name="quote_families[]" value="control4"> Control4</label><label><input class="fam" type="checkbox" name="quote_families[]" value="shelly"> Shelly</label></div><p style="max-width:360px"><label>Plantilla principal</label><select name="quote_template_family" id="template"><option value="lifesmart">LifeSmart</option><option value="control4">Control4</option><option value="shelly">Shelly</option></select></p></div><div class="card"><h2>3. Productos</h2><div class="grid"><p class="c6"><label>Lista de precios</label><select id="priceList" name="price_list_id" required><?php foreach($lists as $idx=>$l):?><option value="<?=$l['id']?>" data-currency="<?=e($l['currency'])?>" <?=$idx===0?'selected':''?>><?=e($l['name'].' · '.$l['currency'])?></option><?php endforeach;?></select></p><p class="c6"><label>Moneda</label><input id="currency" readonly></p></div><div class="items"><table><thead><tr><th style="width:30%">Producto</th><th>Referencia interna</th><th>Marca</th><th>Cantidad</th><th>Unitario</th><th>Subtotal</th><th></th></tr></thead><tbody id="itemBody"></tbody></table></div><p><button type="button" class="btn gray" id="addItem">+ Agregar producto</button></p><div class="grid"><p class="c4"><label>Mano de obra</label><input type="number" min="0" step=".01" name="labor_amount" value="0"></p><p class="c4"><label>IVA materiales</label><select name="materials_tax_mode"><option value="sin_iva">Sin IVA</option><option value="iva_incluido">IVA incluido</option><option value="mas_iva">Más IVA</option></select></p><p class="c4"><label>IVA % materiales</label><input type="number" step=".01" name="materials_vat_rate" value="21"></p><p class="c4"><label>IVA mano de obra</label><select name="labor_tax_mode"><option value="sin_iva">Sin IVA</option><option value="iva_incluido">IVA incluido</option><option value="mas_iva">Más IVA</option></select></p><p class="c4"><label>IVA % mano de obra</label><input type="number" step=".01" name="labor_vat_rate" value="21"></p><div class="c4"><label>Total materiales</label><div id="materialsTotal" style="font-size:22px;font-weight:800">0,00</div></div></div><p><label>Notas / alcance</label><textarea name="notes" rows="4"></textarea></p><button class="btn">Guardar presupuesto</button></div></form></main><script>
const projects=<?=json_encode($projects,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,versions=<?=json_encode($versions)?>,products=<?=json_encode($productJson,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,prices=<?=json_encode($priceJson)?>,lists=<?=json_encode($listJson)?>,preProject=<?=$preProject?>;
const client=document.getElementById('client'),project=document.getElementById('project'),version=document.getElementById('version'),priceList=document.getElementById('priceList'),currency=document.getElementById('currency'),body=document.getElementById('itemBody');let rowNo=0;
function fillProjects(){const cid=Number(client.value);project.innerHTML='<option value="">Seleccionar proyecto…</option>';projects.filter(p=>Number(p.client_id)===cid).forEach(p=>{const o=document.createElement('option');o.value=p.id;o.textContent=p.project_number+' · '+p.name;if(Number(p.id)===preProject)o.selected=true;project.appendChild(o)});syncVersion()}
function syncVersion(){version.value=versions[project.value]||1}
function productOptions(){let h='<option value="">Seleccionar producto…</option>';Object.values(products).forEach(p=>{const ref=p.sku?`${p.sku} · `:'';h+=`<option value="${p.id}">${ref}${p.name}</option>`});return h}
function priceFor(listId,productId,seen=[]){listId=Number(listId);productId=Number(productId);if(!listId||seen.includes(listId))return null;const direct=prices[listId]?.[productId];if(direct!==undefined&&direct!==null)return Number(direct);const l=lists[listId];if(!l||!l.base)return null;const base=priceFor(l.base,productId,[...seen,listId]);if(base===null)return null;return l.discount===null?base:Math.round(base*(1-Number(l.discount)/100)*100)/100}
function addRow(){const i=rowNo++,tr=document.createElement('tr');tr.innerHTML=`<td><select class="prod" name="items[${i}][product_id]" required>${productOptions()}</select></td><td class="ref">—</td><td><select class="brand" name="items[${i}][brand]"><option>LifeSmart</option><option>Control4</option><option>Shelly</option><option>Hikvision / Luma</option><option>Ubiquiti</option><option>Otro</option></select></td><td><input class="qty" type="number" min="0.01" step=".01" name="items[${i}][quantity]" value="1"></td><td><input class="unit" type="number" min="0" step=".01" name="items[${i}][unit_price]" value="0"></td><td class="sub">0,00</td><td><button type="button" class="btn gray remove">×</button></td>`;body.appendChild(tr);const prod=tr.querySelector('.prod'),brand=tr.querySelector('.brand'),unit=tr.querySelector('.unit'),qty=tr.querySelector('.qty'),ref=tr.querySelector('.ref');function sync(){const p=products[prod.value];if(p){brand.value=p.brand;ref.textContent=p.sku||'—';const val=priceFor(priceList.value,p.id);unit.value=val===null?0:val}calc()}prod.addEventListener('change',sync);unit.addEventListener('input',calc);qty.addEventListener('input',calc);tr.querySelector('.remove').onclick=()=>{tr.remove();calc()}}
function calc(){let t=0;body.querySelectorAll('tr').forEach(tr=>{const q=Number(tr.querySelector('.qty').value)||0,u=Number(tr.querySelector('.unit').value)||0,s=q*u;t+=s;tr.querySelector('.sub').textContent=s.toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2})});document.getElementById('materialsTotal').textContent=t.toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2})}
function syncList(){currency.value=priceList.selectedOptions[0]?.dataset.currency||'—';body.querySelectorAll('.prod').forEach(x=>x.dispatchEvent(new Event('change')))}
client.addEventListener('change',fillProjects);project.addEventListener('change',syncVersion);priceList.addEventListener('change',syncList);document.getElementById('addItem').onclick=addRow;fillProjects();syncList();addRow();
</script></body></html>